-- 403: Original BrillaPrep WASSCE Core Mathematics sprint 1 beta questions, part 1 of 8 (batch wassce-core-math-sprint1-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_403_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_403_guard;
INSERT INTO _migration_403_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_001' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Simplify 3x + 5x − 2x.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 6x","B. 10x","C. 5x","D. x"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Collect like terms: 3x + 5x − 2x = (3 + 5 − 2)x = 6x. Therefore the correct answer is A: 6x.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Simplify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_001' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_403_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_002' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the equation x + 7 = 15.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = 22","B. x = 8","C. x = −8","D. x = 7"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Subtract 7 from both sides: x = 15 − 7 = 8. Check: 8 + 7 = 15, as required. Therefore the correct answer is B: x = 8.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_002' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_403_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_003' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Expand the expression 3(a + 4).' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 3a + 4","B. a + 12","C. 3a + 12","D. 3a + 7"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Multiply each term inside the bracket by 3: 3 × a = 3a and 3 × 4 = 12, giving 3a + 12. Therefore the correct answer is C: 3a + 12.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Expand' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_003' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_403_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_004' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Given that y = 2x − 3, find the value of y when x = 5.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 13","B. 4","C. 2","D. 7"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Substitute x = 5 into the formula: y = 2(5) − 3 = 10 − 3 = 7. Therefore the correct answer is D: 7.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Evaluate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_004' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_403_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_005' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the equation 3(x − 2) = 12.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = 6","B. x = 4","C. x = 14/3","D. x = 2"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Divide both sides by 3: x − 2 = 4. Add 2 to both sides: x = 6. Check: 3(6 − 2) = 3 × 4 = 12, as required. Therefore the correct answer is A: x = 6.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_005' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_403_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_006' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Make t the subject of the formula v = u + at.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. t = (v + u)/a","B. t = (v − u)/a","C. t = a(v − u)","D. t = v − u − a"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Subtract u from both sides: at = v − u. Then divide both sides by a: t = (v − u)/a. Therefore the correct answer is B: t = (v − u)/a.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Rearrange' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_006' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_001', 'topic_wcoremath_algebra', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Simplify 3x + 5x − 2x.', 'multiple_choice', NULL, '["A. 6x","B. 10x","C. 5x","D. x"]', 'A', 'Collect like terms: 3x + 5x − 2x = (3 + 5 − 2)x = 6x. Therefore the correct answer is A: 6x.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Simplify', 'AO1', NULL, NULL, 'board_waec');
