INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_004', 'topic_wcoremath_algebra', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Given that y = 2x − 3, find the value of y when x = 5.', 'multiple_choice', NULL, '["A. 13","B. 4","C. 2","D. 7"]', 'D', 'Substitute x = 5 into the formula: y = 2(5) − 3 = 10 − 3 = 7. Therefore the correct answer is D: 7.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Evaluate', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_005', 'topic_wcoremath_algebra', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the equation 3(x − 2) = 12.', 'multiple_choice', NULL, '["A. x = 6","B. x = 4","C. x = 14/3","D. x = 2"]', 'A', 'Divide both sides by 3: x − 2 = 4. Add 2 to both sides: x = 6. Check: 3(6 − 2) = 3 × 4 = 12, as required. Therefore the correct answer is A: x = 6.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_006', 'topic_wcoremath_algebra', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Make t the subject of the formula v = u + at.', 'multiple_choice', NULL, '["A. t = (v + u)/a","B. t = (v − u)/a","C. t = a(v − u)","D. t = v − u − a"]', 'B', 'Subtract u from both sides: at = v − u. Then divide both sides by a: t = (v − u)/a. Therefore the correct answer is B: t = (v − u)/a.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Rearrange', 'AO2', NULL, NULL, 'board_waec');
